# -*- coding: utf-8 -*-
import os, sys, base64, subprocess, tempfile
ROOT=os.getcwd(); ip=os.path.join(ROOT,'index.html'); src=open(ip,encoding='utf-8').read()

SALES_M=''
SALES_F=''

# Validate both decode to JPEG (abort on corruption)
for nm,v in (('SALES_M',SALES_M),('SALES_F',SALES_F)):
    assert base64.b64decode(v + '==')[:3]==b'\xff\xd8\xff', 'CORRUPT base64 for %s -- re-copy the file' % nm

# 1) Inject the 2 new sales constants once, right after the existing _HERO_F_CAR line (do NOT touch existing 4)
if 'window._HERO_SALES_M' not in src:
    anchorL = [ln for ln in src.split(chr(10)) if ln.startswith('window._HERO_F_CAR=')]
    assert len(anchorL)==1, 'F_CAR anchor not unique'
    a = anchorL[0]
    add = a + chr(10) + "window._HERO_SALES_M='data:image/jpeg;base64,"+SALES_M+"';" + chr(10) + "window._HERO_SALES_F='data:image/jpeg;base64,"+SALES_F+"';"
    src = src.replace(a, add, 1)

# 2) Split the combined branch: courier keeps existing logic; sales -> gender-only, new photos
OLD = ("    if(rk === 'courier' || rk === 'sales'){\n"
       "      var _fem=(gender==='f'||gender==='female');\n"
       "      var _car=((vehicleType||'moto').toLowerCase()==='car');\n"
       "      if(_fem) return _car ? window._HERO_F_CAR : window._HERO_F_MOTO;\n"
       "      return _car ? window._HERO_M_CAR : window._HERO_M_MOTO;\n"
       "    }")
NEW = ("    if(rk === 'sales'){\n"
       "      var _femS=(gender==='f'||gender==='female');\n"
       "      return _femS ? window._HERO_SALES_F : window._HERO_SALES_M;\n"
       "    }\n"
       "    if(rk === 'courier'){\n"
       "      var _fem=(gender==='f'||gender==='female');\n"
       "      var _car=((vehicleType||'moto').toLowerCase()==='car');\n"
       "      if(_fem) return _car ? window._HERO_F_CAR : window._HERO_F_MOTO;\n"
       "      return _car ? window._HERO_M_CAR : window._HERO_M_MOTO;\n"
       "    }")
assert src.count(OLD)==1, 'branch block not found uniquely'
src = src.replace(OLD, NEW, 1)

open(ip,'w',encoding='utf-8').write(src)

# 3) Syntax gate: every inline <script> in index.html
html=open(ip,encoding='utf-8').read(); low=html.lower(); i=0; n=0
while True:
    j=low.find('<script', i)
    if j==-1: break
    gt=html.find('>', j); end=low.find('</script>', gt+1)
    if gt==-1 or end==-1: break
    attrs=html[j+7:gt]; body=html[gt+1:end]; i=end+9
    if 'src=' in attrs.lower() or not body.strip(): continue
    n+=1
    tf=tempfile.NamedTemporaryFile('w',suffix='.js',delete=False,encoding='utf-8'); tf.write(body); tf.close()
    r=subprocess.run(['node','--check',tf.name],capture_output=True,text=True); os.remove(tf.name)
    if r.returncode: sys.stderr.write('INLINE #%d FAIL\n%s\n'%(n,r.stderr)); sys.exit(1)
print('OK: sales covers added (gender-only); courier untouched; %d inline scripts pass' % n)
